export const HEC1_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/hec1-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getHec1StdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(HEC1_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
